void generate_download_path(uint32_t download_id, const content_DownloadTargetCallback* callback, const base_FilePath* suggested_path) {
    // Ensure the function is called on the UI thread
    DCHECK(IsUIThread());

    base_FilePath file_path = *suggested_path;
    base_FilePath file_name = base_FilePath_GetBaseName(file_path);
    base_FilePath dir_path = base_FilePath_GetDirName(file_path);

    // Append ".crdownload" to the file name
    base_FilePath new_file_name = base_FilePath_Concat(file_name, base_FilePath_FromString(".crdownload"));
    base_FilePath new_path = base_FilePath_Concat(dir_path, new_file_name);

    // Set the target disposition to REUSE, danger type to NOT_DANGEROUS
    DownloadTargetCallback_SetTargetDisposition(callback, TARGET_DISPOSITION_REUSE);
    DownloadTargetCallback_SetDangerType(callback, DANGER_TYPE_NOT_DANGEROUS);
    DownloadTargetCallback_SetFullPath(callback, &new_path);
}

void generate_download_path(uint32_t download_id, const content_DownloadTargetCallback* callback, const base_FilePath* suggested_path) {
  // Ensure that this function is called on the UI thread
  if (!content_BrowserThreadCurrentlyOn(content_BrowserThread_UI)) {
    return;
  }

  // Construct the file name with ".crdownload" extension
  char file_name[256];
  snprintf(file_name, sizeof(file_name), "%s.crdownload", base_FilePath_BaseName(suggested_path)->value);

  // Update the suggested path with the new file name
  base_FilePath new_path;
  base_FilePath_Set(&new_path, suggested_path->value);
  base_FilePath_Append(&new_path, file_name);

  // Specify the target disposition, danger type, and the new path
  content_DownloadTargetCallback_Invoke(callback, &new_path, 0 /* TARGET_DISPOSITION_DEFAULT */, 0 /* DANGEROUS_TYPE_NOT_DANGEROUS */);
}

void generate_download_path(uint32_t download_id, const content_DownloadTargetCallback* callback, const base_FilePath* suggested_path) {
    // Ensure this is called on the UI thread (assumed to be a pre-condition here)
    base_FilePath file_name = base_FilePath_from_string(base_FilePath_get_base_name(suggested_path));
    base_FilePath file_dir = base_FilePath_get_dirname(suggested_path);
    base_FilePath temp_name = base_FilePath_concat(&file_dir, base_FilePath_get_value(&file_name));
    base_FilePath final_path = base_FilePath_from_string(base_FilePath_get_value(&temp_name));

    // Append ".crdownload" to the final path
    char* crdownload_suffix = ".crdownload";
    size_t final_path_length = strlen(base_FilePath_get_value(&final_path));
    size_t crdownload_length = strlen(crdownload_suffix);
    char* updated_path = (char*)malloc(final_path_length + crdownload_length + 1);

    strcpy(updated_path, base_FilePath_get_value(&final_path));
    strcat(updated_path, crdownload_suffix);

    // Execute the callback with the generated path
    callback->invoke(callback, download_id, updated_path, TARGET_DISPOSITION_PROMPT, DANGER_TYPE_NOT_DANGEROUS);
    free(updated_path);
}

void generate_download_path(uint32_t download_id, const content::DownloadTargetCallback& callback, const base::FilePath& suggested_path) {
    // Check that it is called on the UI thread
    #ifdef DCHECK_CURRENTLY_ON
    DCHECK_CURRENTLY_ON(BrowserThread::UI);
    #endif

    base::FilePath file_name = suggested_path.BaseName();
    std::string file_name_str = file_name.value();
    file_name_str += ".crdownload";

    base::FilePath new_path = suggested_path.DirName().Append(base::FilePath::FromUTF8Unsafe(file_name_str));

    callback.Run(new_path, DownloadItem::TARGET_DISPOSITION_RENAME, DownloadItem::DOWNLOAD_DANGER_TYPE_NOT_DANGEROUS, NULL, NULL);
}
